import unittest
from shop.money import round_cents, add_tax
from shop.cart import line_total, subtotal
from shop.invoice import invoice_total


class H(unittest.TestCase):
    def test_half_up(self):
        for amount, want in ((0.125, 0.13), (2.675, 2.68), (1.005, 1.01), (0.135, 0.14), (8.345, 8.35), (10.0, 10.0), (0.124, 0.12), (3.14159, 3.14)):
            self.assertEqual(round_cents(amount), want, amount)

    def test_lines(self):
        self.assertEqual(line_total(0.25, 1, 0.5), 0.13)
        self.assertEqual(line_total(5.35, 1, 0.5), 2.68)
        self.assertEqual(subtotal([(0.25, 1, 0.5), (5.35, 1, 0.5)]), 2.81)

    def test_tax(self):
        self.assertEqual(add_tax(20.5, 0.5), 30.75)
        self.assertEqual(add_tax(0.5, 0.25), 0.63)

    def test_invoice(self):
        self.assertEqual(invoice_total([(0.25, 1, 0.5)], 0.0), 0.13)
        self.assertEqual(invoice_total([(5.35, 1, 0.5)], 0.0), 2.68)
        self.assertEqual(invoice_total([(10.00, 2, 0.0)], 0.10), 22.00)


if __name__ == "__main__":
    unittest.main()
